// build/texel logs/games.txt 3000
// build/texel logs/games.txt dump 4 > positions.txt (training data for tools/train/train.py, 4 is the optional search depth for the labels
// build/texel positions.txt relabel > relabelled.txt (recomputes the linear score of a dump, for example after changing the weights)
// Uses the file generated by the arena or by selfplay

#include "core/GameHistory.hpp"
#include "core/Position.hpp"
#include "core/Translator.hpp"
#include "engine/Evaluation.hpp"
#include "engine/Network.hpp"
#include "engine/Search.hpp"
#include <algorithm>
#include <array>
#include <chrono>
#include <cmath>
#include <cstdio>
#include <fstream>
#include <iostream>
#include <sstream>
#include <stdexcept>
#include <string>
#include <vector>

namespace {

constexpr int initialSkippedPlies = 8;
constexpr double testFraction = 0.1; // Fraction of games used to test and not train the evaluation weights
static_assert(testFraction >= 0 && testFraction <= 1, "testFraction must be in [0, 1]");
const double K = std::log(10.0) / 400; // Converts the evaluation score to the exponent, so that e^(K*E) = 10^(E/400), +400 means 10:1 odds

using Vector = std::array<double, FeatureCount>;

struct Sample {
    Vector features;         // From White's point of view
    double whiteScore;       // 1, 0.5 or 0
    Position position;       // For the dump
    std::string searchScore; // The search score stored by selfplay, from White's point of view, empty if none
};

struct Data {
    std::vector<Sample> train;
    std::vector<Sample> test;
    int games = 0;
    int reachedMaxPlies = 0;
};

// A position is quiet if the side to move has no capture and no winning move
bool isQuiet(const Position &position, const std::vector<Move> &legal) {
    if (legal.empty())
        return false;
    for (const Move &move : legal) {
        Position next = position;
        if (next.apply(move) > 0 || next.outcome != Outcome::Ongoing)
            return false;
    }
    return true;
}

Data load(const std::string &path) {
    std::ifstream file(path);
    if (!file)
        throw std::runtime_error("Cannot open " + path);

    Data data;
    std::string line;
    for (int lineNumber = 1; std::getline(file, line); lineNumber++) {
        // Loads the data from the line
        const std::string where = path + ":" + std::to_string(lineNumber) + ": ";

        // selfplay writes the search score of each ply after a "|" ("-" for the random opening)
        const size_t bar = line.find('|');
        std::vector<std::string> searchScores;
        if (bar != std::string::npos) {
            std::istringstream scores(line.substr(bar + 1));
            for (std::string score; scores >> score;)
                searchScores.push_back(score);
        }

        std::istringstream words(line.substr(0, bar));
        double whiteScore = 0;
        int reachedMaxPlies = 0;
        if (!(words >> whiteScore >> reachedMaxPlies))
            throw std::runtime_error(where + "expected WHITE_SCORE REACHED_MAX_PLIES MOVES... [| SEARCH_SCORES...]");
        if (reachedMaxPlies) {
            data.reachedMaxPlies++;
            continue;
        }
        data.games++;

        const int pair = (lineNumber - 1) / 2;
        const bool isTest = std::floor((pair + 1) * testFraction) > std::floor(pair * testFraction);
        std::vector<Sample> &set = isTest ? data.test : data.train;

        Position position = Position::start();
        GameHistory history;
        std::string text;
        int ply = 0;
        for (; words >> text; ply++) {
            std::vector<Move> legal;
            position.calculateLegalMoves(legal);
            Move move{};
            if (position.outcome != Outcome::Ongoing || !parseMove(text, move) || std::find(legal.begin(), legal.end(), move) == legal.end())
                throw std::runtime_error(where + "illegal move " + text + " at ply " + std::to_string(ply + 1));

            if (ply >= initialSkippedPlies && isQuiet(position, legal)) {
                const Features features = computeFeatures(position);
                Sample sample{};
                std::copy(features.begin(), features.end(), sample.features.begin());
                sample.whiteScore = whiteScore;
                sample.position = position;
                if (!searchScores.empty() && ply < static_cast<int>(searchScores.size()) && searchScores[ply] != "-")
                    sample.searchScore = searchScores[ply];
                set.push_back(sample);
            }

            const bool captured = position.apply(move) > 0;
            if (history.push(position, captured))
                position.outcome = Outcome::Draw;
        }
        if (!searchScores.empty() && static_cast<int>(searchScores.size()) != ply)
            throw std::runtime_error(where + "expected one search score per move");
    }
    return data;
}

double whiteEval(const Vector &weights, const Sample &sample) {
    double score = 0;
    for (int i = 0; i < FeatureCount; i++)
        score += weights[i] * sample.features[i];
    return score;
}

// ln(1 + e^z) without overflow for large z
// For z > 0: ln(1 + e^z) = ln(e^z * (1 + e^-z)) = z + ln(1 + e^-z)
// For z < 0 there's no overflow
double softplus(double z) {
    return std::max(z, 0.0) + std::log1p(std::exp(-std::abs(z)));
}

// Mean cross-entropy between the predicted and the real White score
double loss(const Vector &weights, const std::vector<Sample> &samples) {
    double total = 0;
    for (const Sample &sample : samples) {
        const double z = K * whiteEval(weights, sample);
        // White's expected score: p = 1 / (1 + e^(-z)), Black's expected score: 1 - p = 1 / (1 + e^z)
        // Cross-entropy: -[y*ln(p) + (1 - y)*ln(1 - p)]
        // y*ln(p) = y*ln( (1 + e^(-z))^(-1) ) = -y*ln(1 + e^(-z)) = -y*softplus(-z)
        // (1 - y)*ln(1 - p) = (1 - y)*ln( (1 + e^z)^(-1) ) = -(1 - y)*ln(1 + e^z) = -(1 - y)*softplus(z)
        // So the cross-entropy is: -[-y*softplus(-z) + -(1 - y)*softplus(z)] = y*softplus(-z) + (1 - y)*softplus(z)
        total += sample.whiteScore * softplus(-z) + (1 - sample.whiteScore) * softplus(z);
    }
    return total / static_cast<double>(samples.size());
}

// The gradient is the derivative of the loss with respect to each weight
// loss = 1/N * sum of cross-entropy, where N is the number of samples
// Cross-entropy = -[y*ln(p) + (1 - y)*ln(1 - p)] = -[y*ln(1 / (1 + e^(-z))) + (1 - y)*ln(1 / (1 + e^z))]
// White's expected score: p = 1 / (1 + e^(-z))
// z = K * whiteEval(weights, sample) = K * sum of weight_i * feature_i
// d(cross-entropy)/d(weight_i) = d(cross-entropy)/d(z) * d(z)/d(weight_i)
// d(z)/d(weight_i) = K * feature_i because z is linear in the weights
// d(cross-entropy)/d(z) = p - y
// d(cross-entropy)/d(weight_i) = (p - y) * K * feature_i
// d(loss)/d(weight_i) = 1/N * sum_{samples} K * (p - y) * feature_i
Vector gradient(const Vector &weights, const std::vector<Sample> &samples) {
    Vector result{};
    for (const Sample &sample : samples) {
        // z = K * whiteEval(weights, sample)
        // White's expected score: p = 1 / (1 + e^(-z))
        // p - y = 1 / (1 + e^(-z)) - y = 1 / (1 + e^(-K * whiteEval(weights, sample))) - sample.whiteScore
        const double error = 1 / (1 + std::exp(-K * whiteEval(weights, sample))) - sample.whiteScore;
        for (int i = 0; i < FeatureCount; i++)
            result[i] += K * error * sample.features[i];
    }
    for (double &value : result)
        value /= static_cast<double>(samples.size());
    return result;
}

/**
 * @brief Copies the default weights of the engine
 *
 * @return The default weights
 */
Vector defaultWeightsVector() {
    Vector weights{};
    std::copy(defaultWeights.begin(), defaultWeights.end(), weights.begin());
    return weights;
}

/**
 * @brief Writes the squares of a piece type
 *
 * @param position The position
 * @param piece The piece type
 * @return The squares as row * 9 + col, "-" if there are none
 */
std::string squares(const Position &position, Piece piece) {
    std::string text;
    for (int square = 0; square < 81; square++)
        if (position.at(square) == piece)
            text += (text.empty() ? "" : ",") + std::to_string(square);
    return text.empty() ? "-" : text;
}

/**
 * @brief Prints one line per position for the network trainer
 * IF_TEST WHITE_SCORE EVALUATION_SCORE SIDE KING WHITE_SQUARES BLACK_SQUARES [SEARCH_SCORE]
 *
 * @param data The positions
 * @param depth The search depth of the label, 0 to use the score stored by selfplay (no label if there is none)
 */
void dump(const Data &data, int depth) {
    const Vector weights = defaultWeightsVector();
    for (const auto *set : {&data.train, &data.test}) {
        for (const Sample &sample : *set) {
            const Position &position = sample.position;
            std::printf("%d %g %ld %d %s %s %s", set == &data.test, sample.whiteScore, std::lround(whiteEval(weights, sample)),
                        position.sideToMove == Side::White ? 0 : 1, squares(position, Piece::King).c_str(),
                        squares(position, Piece::White).c_str(), squares(position, Piece::Black).c_str());
            if (depth > 0) {
                const auto noDeadline = std::chrono::steady_clock::now() + std::chrono::hours(24);
                const int score = search(position, GameHistory{}, noDeadline, depth).score;
                std::printf(" %d", position.sideToMove == Side::White ? score : -score);
            } else if (!sample.searchScore.empty())
                std::printf(" %s", sample.searchScore.c_str());
            std::printf("\n");
        }
    }
}

/**
 * @brief Rewrites the linear score of every line of a dump with the current weights, keeping the other columns
 *
 * @param path The dump
 */
void relabel(const std::string &path) {
    std::ifstream file(path);
    if (!file)
        throw std::runtime_error("Cannot open " + path);
    std::string line;
    while (std::getline(file, line)) {
        std::istringstream words(line);
        std::string test, result, oldScore, side, king, white, black, rest;
        if (!(words >> test >> result >> oldScore >> side >> king >> white >> black))
            throw std::runtime_error("Bad line: " + line);
        std::getline(words, rest);

        Position position;
        position.sideToMove = side == "0" ? Side::White : Side::Black;
        for (const auto &[squares, piece] : {std::pair{king, Piece::King}, {white, Piece::White}, {black, Piece::Black}}) {
            std::istringstream list(squares);
            std::string square;
            while (squares != "-" && std::getline(list, square, ','))
                position.put(std::stoi(square), piece);
        }
        std::printf("%s %s %d %s %s %s %s%s\n", test.c_str(), result.c_str(), linearScore(position), side.c_str(), king.c_str(),
                    white.c_str(), black.c_str(), rest.c_str());
    }
}

} // namespace

int main(int argc, char *argv[]) {
    const bool dumping = argc >= 3 && std::string(argv[2]) == "dump";
    if (argc < 2 || argc > (dumping ? 4 : 3)) {
        std::cerr << "Usage: texel <games file> [iterations (default 3000)]\n"
                     "       texel <games file> dump [search depth (default 0, no search)]\n"
                     "       texel <positions file> relabel"
                  << std::endl;
        return 1;
    }
    try {
        if (argc == 3 && std::string(argv[2]) == "relabel") {
            relabel(argv[1]);
            return 0;
        }
        loadNetworkFromEnvironment(); // Only used for the search labels
        const Data data = load(argv[1]);
        if (dumping) {
            dump(data, argc == 4 ? std::stoi(argv[3]) : 0);
            return 0;
        }

        const int iterations = argc == 3 ? std::stoi(argv[2]) : 3000;
        std::printf("games %d (%d reached max plies, skipped)  positions: train %zu, test %zu\n",
                    data.games, data.reachedMaxPlies, data.train.size(), data.test.size());
        if (data.train.empty() || data.test.empty())
            throw std::runtime_error("Not enough quiet positions: play more games");

        Vector weights = defaultWeightsVector();

        double bestLoss = loss(weights, data.test);
        Vector best = weights;
        int bestIteration = 0;
        std::printf("current weights: train %.5f  test %.5f\n", loss(weights, data.train), bestLoss);

        // Adam
        constexpr double learningRate = 2;
        constexpr double beta1 = 0.9;
        constexpr double beta2 = 0.999;
        Vector mean{};
        Vector meanSquare{};
        for (int iteration = 1; iteration <= iterations; iteration++) {
            const Vector g = gradient(weights, data.train);
            for (int i = 0; i < FeatureCount; i++) {
                mean[i] = beta1 * mean[i] + (1 - beta1) * g[i];                    // Moving average, beta1 is the weight of the previous mean, 1 - beta1 is the weight of the new gradient
                meanSquare[i] = beta2 * meanSquare[i] + (1 - beta2) * g[i] * g[i]; // Moving average of the squared gradient, beta2 is the weight of the previous mean square, 1 - beta2 is the weight of the new squared gradient
                // Unbiased estimates of the mean and mean square, because the moving averages are initialized to 0
                const double meanUnbiased = mean[i] / (1 - std::pow(beta1, iteration));
                const double meanSquareUnbiased = meanSquare[i] / (1 - std::pow(beta2, iteration));
                weights[i] -= learningRate * meanUnbiased / (std::sqrt(meanSquareUnbiased) + 1e-12);
            }

            // Keep the weights from the iteration with the best test loss
            if (iteration % 100 == 0 || iteration == iterations) {
                const double testLoss = loss(weights, data.test);
                if (testLoss < bestLoss) {
                    bestLoss = testLoss;
                    best = weights;
                    bestIteration = iteration;
                }
                if (iteration % 500 == 0)
                    std::printf("iteration %d: train %.5f  test %.5f\n", iteration, loss(weights, data.train), testLoss);
            }
        }

        std::printf("best test %.5f at iteration %d\n", bestLoss, bestIteration);
        std::printf("weights in Feature order (Evaluation.hpp):\n{");
        for (int i = 0; i < FeatureCount; i++)
            std::printf("%s%ld", i ? ", " : "", std::lround(best[i]));
        std::printf("}\n");
    } catch (const std::exception &error) {
        std::cerr << error.what() << std::endl;
        return 1;
    }
    return 0;
}
